{
  "identity": {
    "name": "Ascending IT (also styled as Ascending-IT)",
    "location": "2128 N Devlin Way, Nampa, ID 83687 (serving Boise and the Treasure Valley)",
    "claims": [
      {
        "statement": "Ascending IT lists its physical street address in Nampa, Idaho.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "2128 N Devlin Way, Nampa, ID 83687"
      },
      {
        "statement": "The company states it serves small to medium businesses across the Treasure Valley and nationwide from the Boise area.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Based in Boise, serving businesses locally across the Treasure Valley and nationwide."
      },
      {
        "statement": "The footer copyright notice identifies the business as Ascending-IT.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "© 2026 Ascending-IT | All Rights Reserved | Site by Modern Penguin"
      }
    ]
  },
  "industry": {
    "industry": "Information Technology Services / Managed Service Provider (MSP) & Cybersecurity",
    "activities": [
      "Managed IT services and 24/7 monitoring",
      "Cybersecurity services (EDR, MDR, anti-phishing, ransomware protection, dark web monitoring)",
      "Cloud and SaaS management (Microsoft 365 and Google Workspace)",
      "IT infrastructure, network, firewall, and patch management",
      "Backup and disaster recovery",
      "Co-managed IT services and Virtual CIO (vCIO) consulting",
      "IT security and compliance assessments (HIPAA, PCI-DSS, FINRA)"
    ],
    "claims": [
      {
        "statement": "Ascending IT provides proactive IT management and built-in cybersecurity for small to medium businesses.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "With 20+ years of experience, Ascending IT delivers proactive IT management and built-in cybersecurity for small to medium businesses across the Treasure Valley."
      },
      {
        "statement": "The company offers 24/7 monitoring, proactive maintenance, and helpdesk support.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Our Boise Managed IT Services provide 24/7 monitoring, proactive maintenance, and fast support to reduce downtime, control costs, and keep your business running."
      },
      {
        "statement": "Ascending IT is an B2B IT managed service provider rather than a residential home-service contractor in HVAC, plumbing, or electrical trades.",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/managed-it-support-boise/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://ascending-it.com/",
    "claims": [
      {
        "statement": "Ascending IT structures its managed IT offerings into three tiers: Silver Package, Gold Package, and Platinum Package.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Silver Package Gold Package Platinum Package"
      },
      {
        "statement": "Every new client engagement starts with a Free IT Assessment delivered within three business days.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/free-it-assessment-boise/",
        "quote": "Your assessment is prepared within 3 business days (unless you’re facing an urgent IT crisis, in which case we fast-track your review)."
      },
      {
        "statement": "The company serves clients across Healthcare, Construction, Finance & Accounting, Professional Services, Manufacturing, Retail, and Hospitality.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Healthcare Construction Finance & Accounting Professional Services Manufacturing Retail Hospitality"
      },
      {
        "statement": "The website includes links for clients to make payments and view support ticket status referencing on-sitesvcs.connectboosterportal.com and onsitesvcs.itclientportal.com.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Make A Payment View Ticket Status"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The company states it assists clients with regulatory compliance frameworks including HIPAA, PCI-DSS, and FINRA, though it does not list its own state business registration numbers or trade licenses on the website.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/boise-it-company/",
        "quote": "From HIPAA to PCI-DSS, and cybersecurity threats to scaling challenges, we provide proactive solutions that give you clarity and confidence."
      }
    ],
    "limitations": "No corporate entity registration numbers, legal formation details, or state contractor/trade license numbers are displayed on the public website pages read."
  },
  "existingSoftware": [
    {
      "product": "on-sitesvcs.connectboosterportal.com (ConnectBooster billing portal)",
      "purpose": "Client billing and online payment portal",
      "evidence": {
        "statement": "The host on-sitesvcs.connectboosterportal.com referenced on the site is likely a ConnectBooster payment portal used for the 'Make A Payment' link.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "onsitesvcs.itclientportal.com (IT Client Portal / PSA ticketing portal)",
      "purpose": "Client support ticket status and service portal",
      "evidence": {
        "statement": "The host onsitesvcs.itclientportal.com referenced on the site is likely a customer-facing PSA ticketing portal used for the 'View Ticket Status' link.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "WordPress with Divi Theme, DiviFlash, Divi Toolbox, and Fluent Forms",
      "purpose": "Content management system, website theme/builder, and web form handling",
      "evidence": {
        "statement": "The script paths containing /wp-includes/, /wp-content/themes/Divi/, /wp-content/plugins/diviflash/, and /wp-content/plugins/fluentform/ indicate the website is built on WordPress using Divi and Fluent Forms.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "CookieYes (cdn-cookieyes.com) and Termageddon (policies.termageddon.com)",
      "purpose": "Cookie consent banner management and embedded privacy policy management",
      "evidence": {
        "statement": "Scripts loaded from cdn-cookieyes.com and policies.termageddon.com indicate the site uses CookieYes for consent management and Termageddon for policy embeds.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "Google Tag Manager / Google Analytics (googletagmanager.com) and Google reCAPTCHA",
      "purpose": "Website analytics tracking and form spam protection",
      "evidence": {
        "statement": "Scripts loaded from www.googletagmanager.com and www.google.com/recaptcha/api.js indicate the site uses Google analytics/tag management and reCAPTCHA.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "Ascending IT already operates a client portal for ticket status and a payment portal, and delivers automated email threat remediation and SaaS monitoring as part of its own managed service offerings.",
      "label": "fact",
      "sourceUrl": "https://ascending-it.com/",
      "quote": "*Automated Email Threat Remediation is for 365/Google Workspace"
    },
    {
      "statement": "The company uses web forms for lead capture via its Contact page and Free IT Assessment request page.",
      "label": "fact",
      "sourceUrl": "https://ascending-it.com/it-support-boise/",
      "quote": "Reach out directly or fill out our Free IT Assessment form to get started."
    }
  ],
  "problems": [
    {
      "problem": "No confirmed operational or automation problems exist on the public website that match ForgeX's home-service contractor offerings.",
      "label": "inference",
      "basis": "Based on https://ascending-it.com/ and https://ascending-it.com/managed-it-support-boise/, Ascending IT is an IT Managed Service Provider with its own technical staff, ticketing portal, payment portal, and automation tooling."
    },
    {
      "problem": "Preparing comprehensive Free IT Assessments within 3 business days could involve manual audit aggregation for the technical team.",
      "label": "hypothesis",
      "basis": "Plausible operational workload for an MSP conducting security and network audits, though unconfirmed from public pages."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Client Ticketing Portal (onsitesvcs.itclientportal.com) and Payment Portal (on-sitesvcs.connectboosterportal.com)",
      "addresses": "Customer support triage, ticket tracking, and invoice collection",
      "alreadyOwned": true
    },
    {
      "solution": "MSP RMM, EDR, MDR, and SaaS Active Monitoring stack",
      "addresses": "Endpoint management, patch management, and automated threat remediation",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended because Ascending IT is an IT Managed Services Provider outside ForgeX's target segment of owner-led home-service contractors (HVAC, plumbing, and electrical) and already operates its own IT management and ticketing systems."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "Not applicable as no ForgeX automation service is recommended for this company."
  },
  "humanReview": [
    "No outreach or implementation is recommended because the company is outside ForgeX's target segment."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Selling contractor-focused automation packages to a Managed IT Services Provider that manages technology and security for its own living would waste sales effort and misalign with ForgeX's core segment."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": []
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner / Founder",
      "Managing Partner / President",
      "Service Manager"
    ],
    "people": [],
    "channels": [
      {
        "kind": "email",
        "value": "[redacted]",
        "sourceUrl": "https://ascending-it.com/"
      }
    ]
  },
  "discovery": {
    "questions": [
      "What PSA and RMM platforms do you currently use to manage client tickets and assessments?",
      "Do you serve HVAC, plumbing, or electrical contractors in the Treasure Valley who might benefit from field-service lead and reporting automation?"
    ],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://ascending-it.com/",
        "usedFor": "Business identity, Nampa physical address, phone and email contact details, service packages (Silver, Gold, Platinum), industries served, and portal host references."
      },
      {
        "url": "https://ascending-it.com/boise-it-company/",
        "usedFor": "Company background, mission, values, and compliance frameworks supported (HIPAA, PCI-DSS)."
      },
      {
        "url": "https://ascending-it.com/it-support-boise/",
        "usedFor": "Contact channels, 24/7 support hours, physical address verification, and contact form details."
      },
      {
        "url": "https://ascending-it.com/managed-it-support-boise/",
        "usedFor": "Detailed breakdown of managed IT, cybersecurity, cloud/SaaS, backup, and vCIO services."
      },
      {
        "url": "https://ascending-it.com/privacy-policy/",
        "usedFor": "Checking for legal entity details and observing embedded policy script references."
      },
      {
        "url": "https://ascending-it.com/free-it-assessment-boise/",
        "usedFor": "Details on the Free IT Assessment process, 3-business-day turnaround, and evaluation criteria."
      }
    ],
    "limitations": [
      "No owners, executives, or managers are named on the website (only a client testimonial first name and last initial is shown, which is excluded per ForgeX rules).",
      "Exact employee headcount and service pricing rates are not disclosed on the website.",
      "State business registration numbers are not listed on the public site, and the privacy policy text is dynamically loaded via a third-party script."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "Ascending IT is a B2B Managed IT Services and Cybersecurity Provider (MSP) rather than an owner-led home-service contractor in HVAC, plumbing, or electrical trades. Furthermore, the company is a technology provider with its own ticketing portal, billing portal, and IT automation capabilities."
  }
}
